package com.teamflow.planning.api;
import com.teamflow.planning.client.RemoteDependencyException; import com.teamflow.planning.client.RemoteReferenceNotFoundException; import org.springframework.dao.OptimisticLockingFailureException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.http.converter.HttpMessageNotReadableException; import java.time.*; import java.util.*;
@RestControllerAdvice public class PlanningExceptionHandler {
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){Map<String,String> f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.put(x.getField(),x.getDefaultMessage()));return error(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Request contains invalid fields",f);}
 @ExceptionHandler({IllegalArgumentException.class,MethodArgumentTypeMismatchException.class,HttpMessageNotReadableException.class}) ResponseEntity<Map<String,Object>> bad(Exception e){return error(HttpStatus.BAD_REQUEST,"BAD_REQUEST",e.getMessage()==null?"Request is invalid":e.getMessage(),Map.of());}
 @ExceptionHandler(RemoteReferenceNotFoundException.class) ResponseEntity<Map<String,Object>> notFound(RemoteReferenceNotFoundException e){return error(HttpStatus.NOT_FOUND,"REMOTE_REFERENCE_NOT_FOUND",e.getMessage(),Map.of());}
 @ExceptionHandler(RemoteDependencyException.class) ResponseEntity<Map<String,Object>> dependency(RemoteDependencyException e){return error(HttpStatus.SERVICE_UNAVAILABLE,"REMOTE_DEPENDENCY_UNAVAILABLE",e.getMessage(),Map.of());}
 @ExceptionHandler(OptimisticLockingFailureException.class) ResponseEntity<Map<String,Object>> conflict(OptimisticLockingFailureException e){return error(HttpStatus.CONFLICT,"STALE_OR_CONCURRENT_OPERATION",e.getMessage(),Map.of());}
 @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,Object>> missing(NoSuchElementException e){return error(HttpStatus.NOT_FOUND,"NOT_FOUND",e.getMessage(),Map.of());}
 private ResponseEntity<Map<String,Object>> error(HttpStatus status,String code,String message,Map<String,String> fields){return ResponseEntity.status(status).body(Map.of("timestamp",OffsetDateTime.now(ZoneOffset.UTC),"status",status.value(),"code",code,"message",message,"fields",fields));}
}
